namespace sv_d00fe2b5890443c6b5cce26dc6fe6b7e.Services;

public class WarehouseState
{
    private string _selectedWarehouseId = "warehouse-a";
    private string _selectedWarehouseName = "Warehouse A";

    public string SelectedWarehouseId => _selectedWarehouseId;
    public string SelectedWarehouseName => _selectedWarehouseName;

    public event Action? OnChange;

    public void SetWarehouse(string id, string name)
    {
        if (_selectedWarehouseId == id) return;
        _selectedWarehouseId = id;
        _selectedWarehouseName = name;
        OnChange?.Invoke();
    }

    public static readonly (string Id, string Name)[] AvailableWarehouses =
    [
        ("warehouse-a", "Warehouse A"),
        ("warehouse-b", "Warehouse B"),
        ("warehouse-c", "Warehouse C"),
        ("warehouse-d", "Warehouse D"),
    ];
}

namespace sv_d00fe2b5890443c6b5cce26dc6fe6b7e.Services;

public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private Timer? _pollingTimer;
    private int _subscriberCount;
    private readonly object _lock = new();
    private readonly Random _random = new();

    public int CurrentLowStockCount { get; private set; }

    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulates a database query — returns a random number between 0 and 15.
        return Task.FromResult(_random.Next(0, 16));
    }

    public void StartPolling()
    {
        lock (_lock)
        {
            _subscriberCount++;
            if (_subscriberCount == 1)
            {
                _pollingTimer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
            }
        }
    }

    public void StopPolling()
    {
        lock (_lock)
        {
            _subscriberCount--;
            if (_subscriberCount <= 0)
            {
                _subscriberCount = 0;
                _pollingTimer?.Dispose();
                _pollingTimer = null;
            }
        }
    }

    private async void PollCallback(object? state)
    {
        var count = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        CurrentLowStockCount = count;
        OnAlertCountChanged?.Invoke();
    }

    private async void OnWarehouseChanged()
    {
        // Immediately refresh when warehouse changes.
        var count = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        CurrentLowStockCount = count;
        OnAlertCountChanged?.Invoke();
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        _pollingTimer?.Dispose();
    }
}

