@page "/dashboard"
@inject sv_d00fe2b5890443c6b5cce26dc6fe6b7e.Services.WarehouseState WarehouseState
@inject sv_d00fe2b5890443c6b5cce26dc6fe6b7e.Services.InventoryAlertService AlertService
@rendermode InteractiveServer
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Site</h5>
                <p class="card-text fs-4">@WarehouseState.SelectedWarehouseName</p>
            </div>
        </div>
    </div>
    <div class="col-md-6">
        <div class="card border-danger">
            <div class="card-body">
                <h5 class="card-title text-danger">Low Stock Alerts</h5>
                <p class="card-text fs-1 text-danger fw-bold">@AlertService.CurrentLowStockCount</p>
                <p class="text-muted">Items below minimum levels at @WarehouseState.SelectedWarehouseName</p>
            </div>
        </div>
    </div>
</div>

<div class="mt-3">
    <small class="text-muted">Polling every 10 seconds. Last update: @_lastUpdate.ToString("HH:mm:ss")</small>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;
    private DateTime _lastUpdate = DateTime.Now;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        _alertHandler = () => InvokeAsync(() =>
        {
            _lastUpdate = DateTime.Now;
            StateHasChanged();
        });

        WarehouseState.OnChange += _warehouseHandler;
        AlertService.OnAlertCountChanged += _alertHandler;

        // Start polling when the dashboard becomes visible.
        AlertService.StartPolling();
    }

    public void Dispose()
    {
